:root {
  color-scheme: light;
  --text: #1f2937;
  --muted: #4b5563;
  --line: #d1d5db;
  --input-border: #6b7280;
  --surface: #ffffff;
  --page: #f3f4f6;
  --accent: #1d4ed8;
  --accent-hover: #1e40af;
  --danger: #b91c1c;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color: var(--text);
  background: var(--page);
}

[hidden] {
  display: none !important;
}

body {
  margin: 0;
}

.container {
  max-width: 760px;
  margin: 0 auto;
  padding: 32px 16px;
}

h1 {
  font-size: 1.75rem;
  margin: 0 0 24px;
}

h2 {
  font-size: 1.125rem;
  margin: 0 0 16px;
}

.panel {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 20px;
  margin-bottom: 24px;
}

.form-grid {
  display: grid;
  gap: 16px;
}

@media (min-width: 640px) {
  .form-grid {
    grid-template-columns: 2fr 2fr 1fr;
  }
}

label {
  display: block;
  font-weight: 600;
  margin-bottom: 4px;
}

input {
  box-sizing: border-box;
  width: 100%;
  padding: 8px 10px;
  font: inherit;
  color: var(--text);
  background: var(--surface);
  border: 1px solid var(--input-border);
  border-radius: 6px;
}

input[aria-invalid="true"] {
  border-color: var(--danger);
}

.field-error {
  margin: 4px 0 0;
  color: var(--danger);
  font-size: 0.875rem;
}

.field-error:empty {
  display: none;
}

.form-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 16px;
}

button {
  font: inherit;
  padding: 8px 14px;
  border-radius: 6px;
  cursor: pointer;
}

button.primary {
  border: 1px solid var(--accent);
  background: var(--accent);
  color: #ffffff;
}

button.primary:hover:not(:disabled) {
  background: var(--accent-hover);
}

button.secondary {
  border: 1px solid var(--input-border);
  background: var(--surface);
  color: var(--text);
}

button.secondary:hover:not(:disabled) {
  background: var(--page);
}

button.danger {
  border: 1px solid var(--danger);
  background: var(--surface);
  color: var(--danger);
}

button.danger:hover:not(:disabled) {
  background: #fef2f2;
}

button:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.status {
  min-height: 1.5em;
  margin: 12px 0 0;
}

.status.error {
  color: var(--danger);
}

.table-wrap {
  overflow-x: auto;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 8px;
}

table {
  width: 100%;
  border-collapse: collapse;
}

th,
td {
  text-align: left;
  padding: 10px 12px;
  border-bottom: 1px solid var(--line);
  vertical-align: top;
}

th {
  font-size: 0.875rem;
  color: var(--muted);
}

td.actions {
  white-space: nowrap;
  text-align: right;
}

td.actions button + button {
  margin-left: 6px;
}

.message {
  color: var(--muted);
  text-align: center;
  padding: 24px 12px;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

